const company = $('Get Company Details').item.json;
const items = $input.all();
const pitches = items.map(it => it.json);
const baseUrl = 'https://cancheros.site';

// Fecha y hora exacta en Colombia (America/Bogota, UTC-5)
const nowBogota = new Date();
const todayDate = nowBogota.toLocaleDateString('en-CA', { timeZone: 'America/Bogota' });

const tomorrowObj = new Date(nowBogota.toLocaleString('en-US', { timeZone: 'America/Bogota' }));
tomorrowObj.setDate(tomorrowObj.getDate() + 1);
const tomorrowDate = tomorrowObj.toLocaleDateString('en-CA', { timeZone: 'America/Bogota' });

const timeFormatter = new Intl.DateTimeFormat('en-US', {
  timeZone: 'America/Bogota',
  hour: 'numeric',
  minute: 'numeric',
  hour12: false
});
const timeParts = timeFormatter.formatToParts(nowBogota);
const currentHour = parseInt(timeParts.find(p => p.type === 'hour').value, 10);
const currentMinutes = parseInt(timeParts.find(p => p.type === 'minute').value, 10);

const currentTimeFormatted = nowBogota.toLocaleTimeString('es-CO', {
  timeZone: 'America/Bogota',
  hour: '2-digit',
  minute: '2-digit',
  hour12: true
});

const pitchesFormatted = pitches.map(p => ({
  id: p.id,
  name: p.name,
  type: p.type || 'Fútbol',
  surface: p.surface || 'Sintética',
  price: p.price_per_hour || 0,
  priceFormatted: `$${(p.price_per_hour || 0).toLocaleString('es-CO')}`,
  link: `${baseUrl}/cancha/${p.id}`
}));

const pitchLinksGuide = pitchesFormatted.map(p => 
  `• Cancha: "${p.name}" (${p.type}, ${p.surface}, ${p.priceFormatted}/hr)
  👉 Link oficial para reservar: ${p.link}`
).join('
');

return [{
  json: {
    companyId: company.id,
    companyName: company.name,
    todayDate,
    tomorrowDate,
    currentHour,
    currentMinutes,
    currentTimeFormatted,
    totalPitches: pitches.length,
    pitchLinksGuide,
    pitchesFormatted,
    baseUrl
  }
}];

