const pitchesCtx = $('Format Pitches Context').item.json;
const currentHour = pitchesCtx.currentHour;
const currentMinutes = pitchesCtx.currentMinutes;
const todayDate = pitchesCtx.todayDate;
const tomorrowDate = pitchesCtx.tomorrowDate;
const baseUrl = 'https://cancheros.site';

function formatTime12(timeStr) {
  if (!timeStr) return '';
  const [h, m] = timeStr.split(':').map(Number);
  const period = h >= 12 ? 'PM' : 'AM';
  const h12 = h % 12 === 0 ? 12 : h % 12;
  return `${h12}:${String(m || 0).padStart(2, '0')} ${period}`;
}

function getUniquePitches(rawItems) {
  const map = new Map();
  for (const item of rawItems) {
    const list = Array.isArray(item) ? item : [item];
    for (const p of list) {
      if (p && p.pitch_id && !map.has(p.pitch_id)) {
        map.set(p.pitch_id, p);
      }
    }
  }
  return Array.from(map.values());
}

function processDayAvailability(dayTitle, dateStr, rawItems, isToday) {
  const pitches = getUniquePitches(rawItems);

  if (pitches.length === 0) {
    return `${dayTitle} (${dateStr}): Sin datos de canchas disponibles.
`;
  }

  const parsed = [];
  for (const p of pitches) {
    const avail = [];
    const booked = [];

    for (const s of (p.slots || [])) {
      if (s.status !== 'available') {
        booked.push(formatTime12(s.time));
        continue;
      }
      if (isToday) {
        const [h] = s.time.split(':').map(Number);
        if (h < currentHour || (h === currentHour && currentMinutes > 20)) {
          continue; // Ya pasó hoy
        }
      }
      avail.push(s);
    }

    parsed.push({
      id: p.pitch_id,
      name: p.pitch_name,
      type: p.pitch_type || 'Fútbol',
      surface: p.surface || 'Sintética',
      price: p.price_per_hour || 70000,
      link: `${baseUrl}/cancha/${p.pitch_id}`,
      avail,
      booked
    });
  }

  const firstAvail = parsed.find(p => p.avail.length > 0);

  let out = `══════════════════════════════════════════
`;
  out += `📅 ${dayTitle} (${dateStr})
`;
  out += `══════════════════════════════════════════
`;

  if (firstAvail) {
    const suggestedCount = Math.min(Math.max(firstAvail.avail.length, 3), 4);
    const suggestedSlots = firstAvail.avail.slice(0, suggestedCount).map(s => {
      const priceFormatted = (s.price || firstAvail.price || 0).toLocaleString('es-CO');
      return `${formatTime12(s.time)} ($${priceFormatted})`;
    }).join(', ');

    out += `⭐ RECOMENDACIÓN PRIORITARIA (PRIMERA CANCHA DISPONIBLE - OFRECE ESTA):
`;
    out += `• Cancha: "${firstAvail.name}" (${firstAvail.type}, ${firstAvail.surface})
`;
    out += `• Horarios disponibles sugeridos: ${suggestedSlots}
`;
    out += `• Link oficial de reserva: ${firstAvail.link}

`;
  } else {
    out += `⚠️ TODAS LAS CANCHAS ESTÁN OCUPADAS / RESERVADAS PARA ESTA FECHA.

`;
  }

  out += `📋 DETALLE DE CANCHAS Y HORARIOS DISPONIBLES:
`;
  for (const p of parsed) {
    if (p.avail.length === 0) {
      out += `• ${p.name}: SIN DISPONIBILIDAD (TODO RESERVADO)
`;
    } else {
      const slotsList = p.avail.map(s => {
        const priceFormatted = (s.price || p.price || 0).toLocaleString('es-CO');
        return `${formatTime12(s.time)} ($${priceFormatted})`;
      }).join(', ');
      out += `• ${p.name}: ${slotsList}
  Link: ${p.link}
`;
    }
    if (p.booked.length > 0) {
      out += `  ⛔ HORAS OCUPADAS (NO OFRECER): ${p.booked.join(', ')}
`;
    }
  }

  return out;
}

let todayRaw = [];
let tomorrowRaw = [];

try {
  todayRaw = $('Get Today Availability').all().map(i => i.json);
} catch (e) {
  todayRaw = [];
}

try {
  tomorrowRaw = $('Get Tomorrow Availability').all().map(i => i.json);
} catch (e) {
  tomorrowRaw = [];
}

const todayBlock = processDayAvailability('DISPONIBILIDAD HOY', todayDate, todayRaw, true);
const tomorrowBlock = processDayAvailability('DISPONIBILIDAD MAÑANA', tomorrowDate, tomorrowRaw, false);

return [{
  json: {
    ...pitchesCtx,
    availabilityContext: `${todayBlock}

${tomorrowBlock}`
  }
}];
